function update(dt){if(!game||game.ended)return;game.time+=dt;const gas=keys.gas||keys.ArrowUp,brake=keys.brake||keys.ArrowDown,steer=(keys.right?1:0)-(keys.left?1:0);game.x=clamp(game.x+steer*dt*(1.75+game.speed*.006),-1.22,1.22);if(Math.abs(game.x)>1){game.speed=Math.max(16,game.speed-30*dt);game.flash=Math.max(game.flash,.45)}if(gas)game.speed+=dt*(22+(game.speed<45?14:0))*game.tune.accel;else game.speed-=dt*7;if(brake)game.speed-=dt*38;if(keys.boost&&!game.boostHeld&&game.boostCd<=0&&game.heat<93){game.boost=1.35;game.boostCd=6.5;game.heat+=12;game.score+=120;showMessage('FRIZIONE RAPIDA! +120')}game.boostHeld=!!keys.boost;if(game.boost>0){game.boost-=dt;game.speed+=dt*31;game.heat+=dt*8}else game.heat-=dt*(gas?1.1:2.1);game.heat=clamp(game.heat,30,100);game.boostCd=Math.max(0,game.boostCd-dt);if(game.heat>88)game.speed-=dt*15;game.speed=clamp(game.speed,0,game.tune.max);game.top=Math.max(game.top,game.speed);game.dist+=dt*(game.speed/75)*1.45;game.rain=clamp((game.dist-34)/6,0,1)*clamp((70-game.dist)/5,0,1);game.spawn-=dt;if(game.spawn<=0){game.spawn=rand(.82,1.22);const r=Math.random();game.objects.push({z:1,lane:rand(-.84,.84),type:r<.57?'cone':r<.82?'puddle':'gate'})}for(const o of game.objects){const previous=o.z;o.z-=dt*(.19+game.speed*.0023);if(previous>.15&&o.z<=.15){if(Math.abs(game.x-o.lane)<(o.type==='puddle'?.25:.21)){game.hits++;game.speed=Math.max(12,game.speed-(o.type==='puddle'?22:17));game.score=Math.max(0,game.score-70);game.flash=.9;game.heat+=o.type==='puddle'?2:0;showMessage(o.type==='puddle'?'ATTENTO, ASFALTO BAGNATO!':'CONO SFIORATO · -70')}else game.score+=100}}game.objects=game.objects.filter(o=>o.z>-.08);game.flash=Math.max(0,game.flash-dt);game.score+=dt*(gas?Math.round(game.speed/9):0);const checkpoint=Math.floor(game.dist/33);if(checkpoint>game.sector){game.sector=checkpoint;showMessage(checkpoint===1?'SETTORE 2 · ASFALTO BAGNATO!':'ULTIMO SETTORE · STRINGI LE LINEE!')}if(game.dist>=100){game.dist=100;endGame(true)}else if(game.time>=game.limit)endGame(false);$('#speed').innerHTML=`${Math.round(game.speed)}<span>km/h</span>`;$('#distance').textContent=`${Math.floor(game.dist)}%`;$('#progress').style.width=`${game.dist}%`;$('#heat').innerHTML=`${Math.round(game.heat)}<span>°</span>`;$('#heat').style.color=game.heat>83?'#ff8755':'#d8f16e';$('#timer').textContent=`${String(Math.floor(game.time/60)).padStart(2,'0')}:${String(Math.floor(game.time%60)).padStart(2,'0')}`;const boostBtn=$('.boost');boostBtn.style.opacity=game.boostCd>0?'.48':'1';boostBtn.textContent=game.boostCd>0?Math.ceil(game.boostCd):'BOOST'}
